syntax:
ContainerType::const_iterator begin() const;
ContainerType::const_iterator end() const;
ContainerType::const_reverse_iterator rbegin() const;
ContainerType::const_reverse_iterator rend() const;

code_example:
#include <iostream>
#include <set>

int main() {
    std::set<int> s = {1, 2, 3, 4, 5};
    // Obtain const iterators for read-only traversal
    for (std::set<int>::const_iterator it = s.cbegin(); it != s.cend(); ++it) {
        std::cout << *it << ' ';
        // *it = 10; // Error: cannot modify through const_iterator
    }
    std::cout << "\n";
    // Reverse iteration with const reverse iterator
    for (std::set<int>::const_reverse_iterator rit = s.crbegin(); rit != s.crend(); ++rit) {
        std::cout << *rit << ' ';
    }
    std::cout << "\n";
    return 0;
}
